-- Hand-edited: a post's comment count (#45-7 '댓글 N'; ADR-0074 7-9) is the number of its comments
-- neither deleted nor hidden — 댓글 and 대댓글 alike, a 대댓글 under a deleted or hidden 댓글
-- included — and every comment that enters or leaves that number moves it, here, in the statement's
-- transaction: an insert of one in view, a deletion of one in view, and a change of `deleted_at`,
-- `hidden_at` or `post_id` that takes one into or out of view or to another post (the author's
-- deletion, #50's hiding and its reversal, #184's removals — whoever writes them). An edit of the
-- body does not fire it. The first comment of a post inserts its row, and concurrent writers of
-- one post queue on that row (ON CONFLICT ... DO UPDATE, then the row lock) until they commit, so
-- no count is lost. A comment leaving a post that has no row is refused rather than ignored: the
-- row exists whenever a comment of the post is in view, so a missing one is a count gone wrong.
-- SECURITY DEFINER, as the table's owner (the migration role): buddha_app reads the counts and
-- writes them through this trigger only (REVOKE below). The search path is fixed so the function
-- reaches nothing but these tables.
CREATE FUNCTION post_comment_counts_follow() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  was_counted boolean := false;
  is_counted boolean := false;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    was_counted := OLD.deleted_at IS NULL AND OLD.hidden_at IS NULL;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    is_counted := NEW.deleted_at IS NULL AND NEW.hidden_at IS NULL;
  END IF;
  IF was_counted AND is_counted AND OLD.post_id = NEW.post_id THEN
    RETURN NULL;
  END IF;
  IF was_counted THEN
    UPDATE post_comment_counts SET count = count - 1 WHERE post_id = OLD.post_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'post %: comment % leaves a comment count that was never kept', OLD.post_id,
        OLD.id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  IF is_counted THEN
    INSERT INTO post_comment_counts AS counted (post_id, count) VALUES (NEW.post_id, 1)
    ON CONFLICT (post_id) DO UPDATE SET count = counted.count + 1;
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE TRIGGER post_comments_keep_count
  AFTER INSERT OR UPDATE OF post_id, deleted_at, hidden_at OR DELETE ON "post_comments"
  FOR EACH ROW EXECUTE FUNCTION post_comment_counts_follow();--> statement-breakpoint
-- Hand-edited: TRUNCATE fires no row trigger, so emptying the comments (the owner's — the reset of
-- docs/RESET.md truncates every table at once) empties their counts too.
CREATE FUNCTION post_comment_counts_clear() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
  DELETE FROM post_comment_counts;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE TRIGGER post_comments_clear_counts
  AFTER TRUNCATE ON "post_comments"
  FOR EACH STATEMENT EXECUTE FUNCTION post_comment_counts_clear();--> statement-breakpoint
-- Hand-edited: buddha_app keeps SELECT of the default privileges and loses the writes — the counts
-- move only with the comments (the trigger above runs as the owner).
REVOKE INSERT, UPDATE, DELETE ON TABLE "post_comment_counts" FROM buddha_app;--> statement-breakpoint
-- Hand-edited: the counts of the comments already written — none where this migration creates
-- post_comments above, but the count is exact wherever it starts from (as 0026 fills its terms).
INSERT INTO "post_comment_counts" ("post_id", "count")
SELECT "post_id", count(*)::integer
FROM "post_comments"
WHERE "deleted_at" IS NULL AND "hidden_at" IS NULL
GROUP BY "post_id";
